import { useEffect, useState } from "react";
import Enquiries from "./Enquiries";
import Reviews from "./Reviews";
import AdminGallery from "./AdminGallery";

export default function Dashboard() {
  const [tab, setTab] = useState("enquiries");
  const [stats, setStats] = useState({
    enquiries: 0,
    pendingReviews: 0,
    images: 0,
  });

  useEffect(() => {
    fetch("http://localhost:5001/admin/stats", {
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    })
      .then((res) => res.json())
      .then((data) => setStats(data))
      .catch(() => {});
  }, []);

  return (
    <div className="min-h-screen bg-black text-white flex">
      {/* SIDEBAR */}
      <aside className="w-64 border-r border-white/10 p-6">
        <h2 className="text-2xl font-bold text-yellow-400 mb-8">
          Bodyzeal Admin
        </h2>

        {["enquiries", "reviews", "gallery"].map((item) => (
          <button
            key={item}
            onClick={() => setTab(item)}
            className={`block w-full mb-3 px-4 py-3 rounded ${
              tab === item
                ? "bg-yellow-400 text-black"
                : "hover:bg-white/10"
            }`}
          >
            {item.toUpperCase()}
          </button>
        ))}
      </aside>

      {/* CONTENT */}
      <main className="flex-1 p-10">
        <div className="grid grid-cols-3 gap-6 mb-10">
          <Stat title="Enquiries" value={stats.enquiries} />
          <Stat title="Pending Reviews" value={stats.pendingReviews} />
          <Stat title="Images" value={stats.images} />
        </div>

        {tab === "enquiries" && <Enquiries />}
        {tab === "reviews" && <Reviews />}
        {tab === "gallery" && <AdminGallery />}
      </main>
    </div>
  );
}

function Stat({ title, value }) {
  return (
    <div className="border border-white/10 rounded p-6">
      <p className="text-gray-400">{title}</p>
      <h3 className="text-3xl font-bold text-yellow-400">{value || 0}</h3>
    </div>
  );
}
